    .filter(el => {
      if (el.classList.contains('no-animate')) return false;
      if (el.classList.contains('alien-animating')) return false;
      if (el.closest('.no-animate')) return false;
      if (window.getComputedStyle(el).display === 'none') return false;

      const skipSelectors = ['.alien-title', 'button', 'input'];
      return !skipSelectors.some(selector => 
        el.matches && el.matches(selector)
      );
    });

  // Sort & group by rows
  elements.sort((a, b) => {
    const rectA = a.getBoundingClientRect();
    const rectB = b.getBoundingClientRect();

    if (Math.abs(rectA.top - rectB.top) < 5) {
      return rectA.left - rectB.left;
    }

    return rectA.top - rectB.top;
  });

  const rows = [];
  let currentTop = -1;
  let currentRow = [];

  elements.forEach(element => {
    const rect = element.getBoundingClientRect();

    if (currentTop === -1 || rect.top > currentTop + 5) {
      if (currentRow.length > 0) {
        rows.push(currentRow);
      }
      currentRow = [element];
      currentTop = rect.top;
    } else {
      currentRow.push(element);
    }
  });

  if (currentRow.length > 0) {
    rows.push(currentRow);
  }

  // Animate rows sequentially
  const animate = async () => {
    for (let i = 0; i < rows.length; i++) {
      await animateRow(rows[i], i);
      await new Promise(resolve => setTimeout(resolve, 30));
    }
  };

  animate();
};

/**
 * Animate a single element's text
 */
export const animateText = (element, options = {}) => {
  if (!element) return null;

  // Skip if already animating
  if (element.classList.contains('alien-animating')) {
    return null;
  }

  const defaults = {
    delay: 0,
    duration: 0.35,
    ease: "sine.inOut"
  };

  const settings = { ...defaults, ...options };

  // Determine the right animation method
  const textContent = element.textContent || '';
  const isTextHeavy = textContent.length > 3 && element.children.length < 3;

  let timeline;

  if (isTextHeavy) {
    timeline = prepTextForAnimation(element);
  } else {
    timeline = animateElement(element, settings);
  }

  // Track this animation
  if (timeline) {
    activeAnimations.push(timeline);
  }

  return timeline;
};

export default {
  animateText,
  animateTextInContainer,
  animateAllContent,
  clearAllAnimations
};
